// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.ReportRun.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(reportrun.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *ReportRunUpsertBulk) UpdateNewValues() *ReportRunUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(reportrun.FieldID)
			}
			if _, exists := b.mutation.UID(); exists {
				s.SetIgnore(reportrun.FieldUID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(reportrun.FieldCreatedAt)
			}
			if _, exists := b.mutation.ReportID(); exists {
				s.SetIgnore(reportrun.FieldReportID)
			}
			if _, exists := b.mutation.Trigger(); exists {
				s.SetIgnore(reportrun.FieldTrigger)
			}
			if _, exists := b.mutation.Dry(); exists {
				s.SetIgnore(reportrun.FieldDry)
			}
			if _, exists := b.mutation.Focus(); exists {
				s.SetIgnore(reportrun.FieldFocus)
			}
			if _, exists := b.mutation.RequestedBy(); exists {
				s.SetIgnore(reportrun.FieldRequestedBy)
			}
		}
	}))
	return u
}

